```
module apbxclk #(
		parameter	C_APB_ADDR_WIDTH = 12,
		parameter	C_APB_DATA_WIDTH = 32,
		parameter [0:0]	OPT_REGISTERED = 1'b0,
		localparam	AW = C_APB_ADDR_WIDTH,
		localparam	DW = C_APB_DATA_WIDTH
	) (
		input	wire			S_APB_PCLK, S_PRESETn,
		input	wire			S_APB_PSEL,
		input	wire			S_APB_PENABLE,
		output	reg			S_APB_PREADY,
		input	wire	[AW-1:0]	S_APB_PADDR,
		input	wire			S_APB_PWRITE,
		input	wire	[DW-1:0]	S_APB_PWDATA,
		input	wire	[DW/8-1:0]	S_APB_PWSTRB,
		input	wire	[2:0]		S_APB_PPROT,
		output	wire	[DW-1:0]	S_APB_PRDATA,
		output	wire			S_APB_PSLVERR,
		input	wire			M_APB_PCLK,
		output	reg			M_PRESETn,
		output	reg			M_APB_PSEL,
		output	reg			M_APB_PENABLE,
		input	wire			M_APB_PREADY,
		output	wire	[AW-1:0]	M_APB_PADDR,
		output	wire			M_APB_PWRITE,
		output	wire	[DW-1:0]	M_APB_PWDATA,
		output	wire	[DW/8-1:0]	M_APB_PWSTRB,
		output	wire	[2:0]		M_APB_PPROT,
		input	wire	[DW-1:0]	M_APB_PRDATA,
		input	wire			M_APB_PSLVERR
	);

	reg [DW-1:0] S_APB_PRDATA_reg;
	reg S_APB_PSLVERR_reg;
	reg M_APB_PSEL_reg;
	reg M_APB_PENABLE_reg;
	reg [AW-1:0] M_APB_PADDR_reg;
	reg M_APB_PWRITE_reg;
	reg [DW-1:0] M_APB_PWDATA_reg;
	reg [DW/8-1:0] M_APB_PWSTRB_reg;
	reg [2:0] M_APB_PPROT_reg;

	always @(posedge S_APB_PCLK or negedge S_PRESETn) begin
		if (~S_PRESETn) begin
			S_APB_PREADY <= 1'b0;
			S_APB_PRDATA_reg <= {DW{1'b0}};
			S_APB_PSLVERR_reg <= 1'b0;
		end else begin
			if (S_APB_PSEL && S_APB_PENABLE) begin
				S_APB_PREADY <= 1'b1;
				if (S_APB_PWRITE) begin
					M_APB_PSEL_reg <= 1'b1;
					M_APB_PENABLE_reg <= 1'b1;
					M_APB_PADDR_reg <= S_APB_PADDR;
					M_APB_PWRITE_reg <= S_APB_PWRITE;
					M_APB_PWDATA_reg <= S_APB_PWDATA;
					M_APB_PWSTRB_reg <= S_APB_PWSTRB;
					M_APB_PPROT_reg <= S_APB_PPROT;
				end else begin
					M_APB_PSEL_reg <= 1'b1;
					M_APB_PENABLE_reg <= 1'b1;
					M_APB_PADDR_reg <= S_APB_PADDR;
					M_APB_PWRITE_reg <= S_APB_PWRITE;
					M_APB_PWDATA_reg <= S_APB_PWDATA;
					M_APB_PWSTRB_reg <= S_APB_PWSTRB;
					M_APB_PPROT_reg <= S_APB_PPROT;
					S_APB_PRDATA_reg <= M_APB_PRDATA;
					S_APB_PSLVERR_reg <= M_APB_PSLVERR;
				end
			end else begin
				S_APB_PREADY <= 1'b0;
				M_APB_PSEL_reg <= 1'b0;
				M_APB_PENABLE_reg <= 1'b0;
				M_APB_PADDR_reg <= {AW{1'b0}};
				M_APB_PWRITE_reg <= 1'b0;
				M_APB_PWDATA_reg <= {DW{1'b0}};
				M_APB_PWSTRB_reg <= {DW/8{1'b0}};
				M_APB_PPROT_reg <= {3{1'b0}};
			end
		end
	end

	always @(posedge M_APB_PCLK or negedge S_PRESETn) begin
		if (~S_PRESETn) begin
			M_PRESETn <= 1'b0;
			M_APB_PSEL <= 1'b0;
			M_APB_PENABLE <= 1'b0;
			M_APB_PADDR <= {AW{1'b0}};
			M_APB_PWRITE <= 1'b0;
			M_APB_PWDATA <= {DW{1'b0}};
			M_APB_PWSTRB <= {DW/8{1'b0}};
			M_APB_PPROT <= {3{1'b0}};
		end else begin
			if (M_APB_PREADY) begin
				M_APB_PSEL <= 1'b0;
				M_APB_PENABLE <= 1'b0;
				M_APB_PADDR <= {AW{1'b0}};
				M_APB_PWRITE <= 1'b0;
				M_APB_PWDATA <= {DW{1'b0}};
				M_APB_PWSTRB <= {DW/8{1'b0}};
				M_APB_PPROT <= {3{1'b0}};
			end else begin
				M_APB_PSEL <= M_APB_PSEL_reg;
				M_APB_PENABLE <= M_APB_PENABLE_reg;
				M_APB_PADDR <= M_APB_PADDR_reg;
				M_APB_PWRITE <= M_APB_PWRITE_reg;
				M_APB_PWDATA <= M_APB_PWDATA_reg;
				M_APB_PWSTRB <= M_APB_PWSTRB_reg;
				M_APB_PPROT <= M_APB_PPROT_reg;
			end
			M_PRESETn <= 1'b1;
		end
	end

	assign S_APB_PRDATA = OPT_REGISTERED ? S_APB_PRDATA_reg : M_APB_PRDATA;
	assign S_APB_PSLVERR = OPT_REGISTERED ? S_APB_PSLVERR_reg : M_APB_PSLVERR;

